// Health PWA Service Worker v1.0.95
// IMPORTANT: Increment version number when deploying updates!

const CACHE_VERSION = '1.0.95';
const CACHE_NAME = `health-pwa-v${CACHE_VERSION}`;
const OFFLINE_URL = '/health_pwa/offline';
const API_CACHE_NAME = `health-pwa-api-v${CACHE_VERSION}`;

// Listen for SKIP_WAITING message to activate new service worker immediately
self.addEventListener('message', (event) =&gt; {
    if (event.data &amp;&amp; event.data.type === 'SKIP_WAITING') {
        self.skipWaiting();
    }
});

// Files to cache for offline functionality
const STATIC_CACHE_URLS = [
    '/health_pwa',
    '/health_pwa/offline',
    `/health_pwa/static/src/css/app.css?v=${CACHE_VERSION}`,
    `/health_pwa/static/src/css/mobile.css?v=${CACHE_VERSION}`,
    `/health_pwa/static/src/js/utils/pwa-utils.js?v=${CACHE_VERSION}`,
    `/health_pwa/static/src/js/app.js?v=${CACHE_VERSION}`,
    `/health_pwa/static/src/js/router.js?v=${CACHE_VERSION}`,
    '/health_pwa/static/icons/icon-192.png',
    // Note: External CDN URLs removed from pre-cache - they fail with CORS errors
    // and cause the entire SW installation to fail, preventing cache updates.
    // These are loaded directly via &lt;script&gt; tags and cached by the browser normally.
];

// API endpoints to cache
const API_CACHE_PATTERNS = [
    /^\/health_pwa\/api\/patients/,
    /^\/health_pwa\/api\/fso/,
    /^\/health_pwa\/api\/teams/,
    /^\/health_pwa\/api\/user/,
];

// Install event - cache static files
self.addEventListener('install', event =&gt; {
    console.log('Service Worker installing...');
    event.waitUntil(
        caches.open(CACHE_NAME)
            .then(cache =&gt; {
                console.log('Caching static files');
                return cache.addAll(STATIC_CACHE_URLS);
            })
            .then(() =&gt; {
                console.log('Service Worker installed successfully');
                return self.skipWaiting();
            })
            .catch(error =&gt; {
                console.error('Service Worker installation failed:', error);
            })
    );
});

// Activate event - clean up old caches
self.addEventListener('activate', event =&gt; {
    console.log('Service Worker activating...');
    event.waitUntil(
        caches.keys().then(cacheNames =&gt; {
            return Promise.all(
                cacheNames.map(cacheName =&gt; {
                    if (cacheName !== CACHE_NAME &amp;&amp; cacheName !== API_CACHE_NAME) {
                        console.log('Deleting old cache:', cacheName);
                        return caches.delete(cacheName);
                    }
                })
            );
        }).then(() =&gt; {
            console.log('Service Worker activated');
            return self.clients.claim();
        })
    );
});

// Fetch event - handle network requests with caching strategy
self.addEventListener('fetch', event =&gt; {
    const request = event.request;
    const url = new URL(request.url);

    // Skip non-GET requests and chrome-extension requests
    if (request.method !== 'GET' || url.protocol === 'chrome-extension:') {
        return;
    }

    // Handle PWA app requests
    if (url.pathname.startsWith('/health_pwa')) {
        if (url.pathname.startsWith('/health_pwa/api/') || url.pathname.startsWith('/health_pwa/sync/')) {
            // API requests - Network First with Cache Fallback
            event.respondWith(handleAPIRequest(request));
        } else if (request.mode === 'navigate' || url.pathname === '/health_pwa' || url.pathname === '/health_pwa/') {
            // Navigation requests (HTML) - Network First to always get latest version
            event.respondWith(handleNavigationRequest(request));
        } else {
            // Static files (JS, CSS, images) - Cache First (versioned via query param)
            event.respondWith(handleStaticRequest(request));
        }
    }
});
// Handle navigation (HTML page) requests with Network First strategy
async function handleNavigationRequest(request) {
    try {
        const response = await fetch(request);
        if (response.ok) {
            // Cache the latest HTML for offline use
            const cache = await caches.open(CACHE_NAME);
            cache.put(request, response.clone());
        }
        return response;
    } catch (error) {
        console.log('Navigation fetch failed, using cache');
        const cache = await caches.open(CACHE_NAME);
        const cachedResponse = await cache.match(request);
        if (cachedResponse) return cachedResponse;
        // Fallback to offline page
        const offlineResponse = await cache.match(OFFLINE_URL);
        return offlineResponse || new Response('Offline', { status: 503 });
    }
}

// Handle API requests with Network First strategy
async function handleAPIRequest(request) {
    const url = new URL(request.url);

    try {
        // Try network first
        const response = await fetch(request);

        // Cache successful GET responses for offline use
        if (response.ok &amp;&amp; request.method === 'GET') {
            const cache = await caches.open(API_CACHE_NAME);
            cache.put(request, response.clone());
        }

        return response;
    } catch (error) {
        console.log('Network failed, trying cache for:', url.pathname);

        // Network failed, try cache
        const cache = await caches.open(API_CACHE_NAME);
        const cachedResponse = await cache.match(request);

        if (cachedResponse) {
            // Add offline indicator header
            const response = cachedResponse.clone();
            response.headers.set('X-Served-By', 'ServiceWorker-Cache');
            return response;
        }

        // Return offline response for API requests
        return new Response(JSON.stringify({
            success: false,
            error: 'Network unavailable and no cached data',
            offline: true,
            timestamp: new Date().toISOString()
        }), {
            status: 503,
            headers: { 'Content-Type': 'application/json' }
        });
    }
}

// Handle static requests with Cache First strategy
async function handleStaticRequest(request) {
    const cache = await caches.open(CACHE_NAME);
    const cachedResponse = await cache.match(request);

    if (cachedResponse) {
        return cachedResponse;
    }

    try {
        const response = await fetch(request);
        if (response.ok) {
            cache.put(request, response.clone());
        }
        return response;
    } catch (error) {
        console.log('Static request failed:', request.url);

        // Return offline page for navigation requests
        if (request.mode === 'navigate') {
            const offlineResponse = await cache.match(OFFLINE_URL);
            return offlineResponse || new Response('Offline', { status: 503 });
        }

        // Return minimal response for other requests
        return new Response('Offline', { status: 503 });
    }
}

// Background sync for offline actions
self.addEventListener('sync', event =&gt; {
    console.log('Background sync triggered:', event.tag);

    if (event.tag === 'health-pwa-sync') {
        event.waitUntil(performBackgroundSync());
    }
});

// Perform background sync
async function performBackgroundSync() {
    try {
        // Get pending sync data from IndexedDB (handled by PouchDB)
        console.log('Performing background sync...');

        // Send message to active clients to trigger sync
        const clients = await self.clients.matchAll();
        clients.forEach(client =&gt; {
            client.postMessage({
                type: 'BACKGROUND_SYNC',
                timestamp: new Date().toISOString()
            });
        });

    } catch (error) {
        console.error('Background sync failed:', error);
    }
}

// Push notification handler
self.addEventListener('push', event =&gt; {
    console.log('[SW] Push notification received');

    let notifData = {
        title: 'Viet Uc',
        body: 'New notification',
        icon: '/health_pwa/static/icons/icon-192.png',
        badge: '/health_pwa/static/icons/icon-96.png',
        tag: 'health-pwa-notification',
        data: {},
    };

    if (event.data) {
        try {
            const payload = event.data.json();
            notifData.title = payload.title || notifData.title;
            notifData.body = payload.body || notifData.body;
            notifData.icon = payload.icon || notifData.icon;
            notifData.badge = payload.badge || notifData.badge;
            notifData.tag = payload.tag || notifData.tag;
            notifData.data = payload.data || {};
        } catch (e) {
            notifData.body = event.data.text();
        }
    }

    // Build notification actions based on type
    let actions = [
        { action: 'open', title: 'Mở / Open' },
        { action: 'close', title: 'Đóng / Close' }
    ];

    // Assignment notifications get Accept/Decline buttons
    if (notifData.data &amp;&amp; notifData.data.type === 'assignment' &amp;&amp; notifData.data.assignment_id) {
        actions = [
            { action: 'accept', title: '✅ Accept' },
            { action: 'decline', title: '❌ Decline' },
        ];
    }

    const options = {
        body: notifData.body,
        icon: notifData.icon,
        badge: notifData.badge,
        vibrate: [200, 100, 200],
        tag: notifData.tag,
        data: notifData.data,
        actions: actions,
        requireInteraction: true,
    };

    event.waitUntil(
        self.registration.showNotification(notifData.title, options).then(() =&gt; {
            // Notify all open clients to refresh notification count
            return self.clients.matchAll({ type: 'window' }).then(clientList =&gt; {
                clientList.forEach(client =&gt; {
                    client.postMessage({ type: 'PUSH_RECEIVED' });
                });
            });
        })
    );
});

// Notification click handler
self.addEventListener('notificationclick', event =&gt; {
    console.log('[SW] Notification clicked:', event.action);
    event.notification.close();

    if (event.action === 'close') return;

    const notifData = event.notification.data || {};
    const assignmentId = notifData.assignment_id;

    // Handle Accept/Decline actions for assignments
    if (assignmentId &amp;&amp; (event.action === 'accept' || event.action === 'decline')) {
        event.waitUntil(
            fetch(`/health_pwa/api/assignments/${assignmentId}/respond`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ action: event.action }),
            }).then(resp =&gt; resp.json()).then(data =&gt; {
                console.log('[SW] Assignment response:', data);
                // Notify clients to refresh
                return self.clients.matchAll({ type: 'window' }).then(clientList =&gt; {
                    clientList.forEach(client =&gt; {
                        client.postMessage({ type: 'PUSH_RECEIVED' });
                    });
                    // If no open clients, show a confirmation notification
                    if (clientList.length === 0) {
                        const msg = event.action === 'accept'
                            ? '✅ Assignment confirmed'
                            : '❌ Assignment declined';
                        return self.registration.showNotification('Viet Uc', {
                            body: msg,
                            icon: '/health_pwa/static/icons/icon-192.png',
                            tag: 'assignment-response',
                        });
                    }
                });
            }).catch(err =&gt; {
                console.error('[SW] Failed to respond to assignment:', err);
                return self.registration.showNotification('Viet Uc', {
                    body: '⚠️ Error responding to assignment. Please open the app.',
                    icon: '/health_pwa/static/icons/icon-192.png',
                    tag: 'assignment-response-error',
                });
            })
        );
        return;
    }

    // Default: open the app (with notifications panel if assignment)
    const urlToOpen = (notifData &amp;&amp; notifData.type === 'assignment')
        ? '/health_pwa#/today?showNotifications=1'
        : (notifData &amp;&amp; notifData.url)
            ? notifData.url
            : '/health_pwa';

    event.waitUntil(
        clients.matchAll({ type: 'window', includeUncontrolled: true }).then(clientList =&gt; {
            // Try to focus existing window
            for (const client of clientList) {
                if (client.url.includes('/health_pwa') &amp;&amp; 'focus' in client) {
                    client.navigate(urlToOpen);
                    return client.focus();
                }
            }
            // Open new window if no existing window
            if (clients.openWindow) {
                return clients.openWindow(urlToOpen);
            }
        })
    );
});

console.log('Health PWA Service Worker loaded successfully');
